mapper.sql:
FROM gb_ai_conversation c
LEFT JOIN gb_ai_conversation_pin p ON p.gb_ai_cp_conversation_id = c.gb_ai_conversation_id
    AND p.gb_ai_cp_user_id = #{userId}

WHERE c.gb_ai_conversation_user_id = #{userId}

    AND c.gb_ai_conversation_department_id = #{departmentId}


    AND c.gb_ai_conversation_distributer_id = #{distributerId}


    AND IFNULL(c.gb_ai_conversation_archived, 0) = 0


    AND (
        c.gb_ai_conversation_title LIKE CONCAT('%', #{keyword}, '%')
        OR EXISTS (
            SELECT 1 FROM gb_ai_message mk
            WHERE mk.gb_ai_message_conversation_id = c.gb_ai_conversation_id
              AND mk.gb_ai_message_content LIKE CONCAT('%', #{keyword}, '%')
            LIMIT 1
        )
    )


    AND EXISTS (
        SELECT 1 FROM gb_ai_conversation_tag ct
        WHERE ct.gb_ai_ct_conversation_id = c.gb_ai_conversation_id
          AND ct.gb_ai_ct_user_id = #{userId}
          AND ct.gb_ai_ct_tag_id = #{tagId}
    )


    AND EXISTS (
        SELECT 1 FROM gb_ai_conversation_notebook cn
        WHERE cn.gb_ai_cnb_conversation_id = c.gb_ai_conversation_id
          AND cn.gb_ai_cnb_user_id = #{userId}
          AND cn.gb_ai_cnb_notebook_id = #{notebookId}
    )


    AND p.gb_ai_cp_id IS NOT NULL


    AND (
        SELECT m.gb_ai_message_status FROM gb_ai_message m
        WHERE m.gb_ai_message_conversation_id = c.gb_ai_conversation_id
          AND m.gb_ai_message_role = 'assistant'
        ORDER BY m.gb_ai_message_create_time DESC, m.gb_ai_message_id DESC
        LIMIT 1
    ) = #{lastRunStatus}

mapper.select:
SELECT m.* FROM gb_ai_message m INNER JOIN ( SELECT gb_ai_message_conversation_id AS cid, MIN(gb_ai_message_id) AS mid FROM gb_ai_message WHERE gb_ai_message_role = 'user' AND gb_ai_message_conversation_id IN
#{id}
GROUP BY gb_ai_message_conversation_id ) t ON m.gb_ai_message_conversation_id = t.cid AND m.gb_ai_message_id = t.mid

SELECT m.* FROM gb_ai_message m INNER JOIN ( SELECT gb_ai_message_conversation_id AS cid, MAX(gb_ai_message_id) AS mid FROM gb_ai_message WHERE gb_ai_message_role = 'assistant' AND gb_ai_message_conversation_id IN
#{id}
GROUP BY gb_ai_message_conversation_id ) t ON m.gb_ai_message_conversation_id = t.cid AND m.gb_ai_message_id = t.mid
